class Solution:
    def countTours(self, A: int, B: int, C: int, D: List[List[int]], E: int) -> int:
        from itertools import accumulate
        MOD = 10**9 + 7
        bad = [set() for _ in range(C + 1)]
        for day, city in D: bad[day].add(city)
        ways = [0] * (A + 1); ways[B] = 1
        for d in range(1, C + 1):
            pre = [0] + list(accumulate(ways[1:]))      # prefix sums over cities
            blocked = bad[d]
            ways = [0] + [0 if c in blocked else (pre[min(A, c + E)] - pre[max(1, c - E) - 1]) % MOD
                          for c in range(1, A + 1)]
        return sum(ways) % MOD

