class Solution {
public:
    int countTours(int A, int B, int C, vector<vector<int>>& D, int E) {
        const long long MOD = 1000000007;
        vector<vector<char>> bad(C + 1, vector<char>(A + 1, 0));
        for (auto& x : D) bad[x[0]][x[1]] = 1;
        vector<long long> ways(A + 1, 0), pre(A + 1, 0); ways[B] = 1;
        for (int d = 1; d <= C; d++) {
            for (int c = 1; c <= A; c++) pre[c] = (pre[c - 1] + ways[c]) % MOD;
            for (int c = 1; c <= A; c++)
                ways[c] = bad[d][c] ? 0 : (pre[min(A, c + E)] - pre[max(1, c - E) - 1] + MOD) % MOD;
        }
        long long s = 0; for (int c = 1; c <= A; c++) s = (s + ways[c]) % MOD;
        return (int) s;
    }
};

